'use strict';
let latest2025,latestError=false,latestLoading=false,latestQuery='',latestOnlyAmounts=false;
const latestPct=v=>v==='-'?'―':v==null?'未収録':Number(v).toLocaleString('ja-JP',{maximumFractionDigits:1})+'%';
function loadLatest(){if(latest2025||latestLoading)return;latestLoading=true;fetch('latest-2025.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{latest2025=d;latestLoading=false;if(state.tab==='latest')render()}).catch(()=>{latestLoading=false;latestError=true;if(state.tab==='latest')render()})}
function latestRows(){const pref=$('#pref').value,q=latestQuery.trim();return db.cities.filter(c=>(!pref||c.pref===pref)&&(!q||(c.pref+c.name+c.code).includes(q))&&(!latestOnlyAmounts||latest2025.basic[c.code]))}
function latestView(){
 if(!latest2025){if(!latestError)loadLatest();return `<section class="panel"><h2>2025年度決算・速報</h2><p role="status">${latestError?'資料を読み込めませんでした。ページを再読み込みしてください。':'2025年度の資料を読み込んでいます…'}</p></section>`}
 const d=latest2025,c=city(),r=d.cities[c?.code],b=d.basic[c?.code],src=d.sources.health2025,bs=b&&d.sources[b.source],rows=latestRows();
 return `<div class="section-top"><h2>2025年度決算・速報</h2><div>${tag('全国1,741団体・47都道府県','green')}${tag('速報値・改訂の可能性あり','amber')}</div></div>
 <div class="note blue"><b>2025年度（令和7年度）の公表済みデータです。</b><br>健全化判断比率は全国1,741市区町村。歳入・歳出総額は大阪府41団体・福岡県60団体を収録。全国共通の税収内訳・目的別／性質別歳出の2025年度詳細表は未収録です。上部の「全国統計年度」と独立した表示で、2024年度の金額を流用していません。</div>
 ${c?`<section class="panel"><div class="section-top" style="margin-top:0"><h3>${esc(c.pref+' '+c.name)}</h3>${tag('2025年度')}</div><div class="grid2">${d.ratioNames.map((n,i)=>`<div class="stat"><span class="label">${esc(n)}</span><strong>${latestPct(r.ratios[i])}</strong><small>${i===2?'原表の3か年平均。単年度の比率ではありません。':i===3?'原表の将来負担比率。将来の予算額ではありません。':'原表の「―」は該当する赤字額等なし。ゼロに変換しません。'}</small></div>`).join('')}</div><p class="small">単位：％。原表の「―」を保持。将来負担比率の「―」は算定上の負担額等がない場合を含みます。これらは財政指標であり、政策成果や行政の優劣を示すものではありません。</p><p class="small">${link(src.url+'#\'1(2)\'!C'+r.sourceRow,src.label+'・シート1(2) '+r.sourceRow+'行')} ／ 公表日 ${src.published}</p>
 ${b?`<h3>同年度の普通会計決算額</h3><div class="stats"><div class="stat primary"><span class="label">歳入総額</span><strong>${oku(b.revenue*b.unit)}</strong></div><div class="stat"><span class="label">歳出総額</span><strong>${oku(b.spending*b.unit)}</strong></div><div class="stat"><span class="label">実質収支</span><strong>${oku(b.balance*b.unit)}</strong></div></div><p class="small">原表単位：${b.unit===1000000?'百万円（四捨五入のため差引・合計に差が生じることがあります）':'千円'}。経常収支比率 ${latestPct(b.currentRatio)}。${link(bs.url,bs.label+'・'+b.sourceRow+'行')}</p>`:`<div class="note">この自治体の2025年度歳入・歳出総額は、この速報データには未収録です。未公表とは限りません。${c.code==='13105'?'文京区の2025年度一般会計は「支出ツリー」の自治体決算年度から確認できます。普通会計とは集計範囲が異なります。':'2024年度の総額と内訳は「まちの財政」で確認できます。'}</div>`}</section>`:`<section class="panel"><h3>全国の2025年度速報</h3><p>下の一覧は全国の公表済みデータです。上部で自治体を選ぶと、その自治体の指標と収録済みの決算額を表示します。</p></section>`}
 <section class="panel" style="margin-top:18px"><h3>全国の2025年度を一覧で見る</h3><p class="small">上部の都道府県で絞り込みできます。歳入・歳出の「未収録」はゼロではありません。大阪市・堺市の総額は今回の大阪府資料の対象外です。</p><div class="compare-controls"><label>自治体名・コード<input id="latestSearch" type="search" placeholder="例：福岡市、檮原町" value="${esc(latestQuery)}"></label><label><input id="latestOnlyAmounts" type="checkbox" ${latestOnlyAmounts?'checked':''}> 歳入・歳出総額の収録団体のみ</label><button class="action" id="latestDownload">表示分をCSVで保存 ↓</button></div><p class="small" role="status">${fmt(rows.length)}団体を表示 ／ 全国の財政指標1,741団体・決算総額101団体</p><div class="tablewrap" style="max-height:560px;overflow:auto"><table><thead><tr><th>自治体</th><th class="num">実質公債費比率</th><th class="num">将来負担比率</th><th class="num">歳入総額</th><th class="num">歳出総額</th></tr></thead><tbody>${rows.map(c=>{const r=d.cities[c.code],b=d.basic[c.code];return `<tr><td>${esc(c.pref+' '+c.name)}<br><small>${c.code}</small></td><td class="num">${latestPct(r.ratios[2])}</td><td class="num">${latestPct(r.ratios[3])}</td><td class="num">${b?oku(b.revenue*b.unit):'未収録'}</td><td class="num">${b?oku(b.spending*b.unit):'未収録'}</td></tr>`}).join('')}</tbody></table></div></section>
 <section class="panel source-list" style="margin-top:18px"><h3>出典・収録範囲・更新</h3>${Object.values(d.sources).map(s=>`${link(s.page,s.label)}<p class="small">${s.count}団体 ／ 公表日 ${s.published} ／ ${link(s.url,'原表Excel')}</p>`).join('')}<p class="small">毎週火曜6:17（日本時間）に原表の訂正を確認します。団体名・都道府県を完全一致で結合し、梼原町／檮原町のみ字体対応。原表の行番号・SHA-256を保持。新しい資料形式や未対応の年度は検証後に取り込みます。</p>${link('latest-2025.json','全件データ・出典・ハッシュ（JSON）')}<p class="small">全国の目的別・性質別の詳細データは総務省の新年度表を検知後、形式と合計を確認して追加します。今回の更新で全国の2025年度支出ツリーや契約・支払先が揃ったわけではありません。</p></section>`;
}
function bindLatest(){const input=$('#latestSearch');if(input)input.addEventListener('input',e=>{const pos=e.target.selectionStart;latestQuery=e.target.value;render();$('#latestSearch').focus();$('#latestSearch').setSelectionRange(pos,pos)});$('#latestOnlyAmounts')?.addEventListener('change',e=>{latestOnlyAmounts=e.target.checked;render()});$('#latestDownload')?.addEventListener('click',()=>{const d=latest2025,header=['年度','都道府県','自治体名','自治体コード',...d.ratioNames.map(x=>x+'(%)'),'歳入総額(原表単位)','歳出総額(原表単位)','原表金額単位(円)','実質収支(原表単位)','経常収支比率(%)','指標出典URL','指標原表行','決算額出典URL','決算額原表行','速報'];const data=latestRows().map(c=>{const r=d.cities[c.code],b=d.basic[c.code];return ['2025',c.pref,c.name,c.code,...r.ratios,b?.revenue??'',b?.spending??'',b?.unit??'',b?.balance??'',b?.currentRatio??'',d.sources.health2025.url,r.sourceRow,b?d.sources[b.source].url:'',b?.sourceRow??'','速報値']});const csv=[header,...data].map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='municipal-fy2025-provisional.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
